WITH valid AS (SELECT id, category, brand, price, cost, launch_date, tags, supplier_id, TRIM(category) AS clean_category FROM products WHERE ARRAY_CONTAINS(tags, 'clearance')), with_dims AS (SELECT e.*, s.rating, s.country FROM valid e LEFT JOIN suppliers s ON e.supplier_id = s.id), metrics AS (SELECT *, ROUND(price / SUM(price) OVER (PARTITION BY country, supplier_id), 4) AS price_share, NTILE(3) OVER (ORDER BY cost, id) AS cost_bucket FROM with_dims) SELECT supplier_id, DATE_TRUNC('QUARTER', launch_date) AS quarter_start, DATE_TRUNC('MONTH', launch_date) AS activity_month, SIZE(COLLECT_SET(category)) AS num_categories, ROUND(AVG(rating), 2) AS avg_rating, COUNT(*) AS event_count, COUNT(DISTINCT brand) AS distinct_brands, SUM(cost_bucket) FILTER (WHERE country = 'SG') AS sg_total_cost_bucket, SUM(price_share) AS total_price_share, GROUPING_ID() AS grouping_id FROM metrics GROUP BY CUBE (supplier_id, DATE_TRUNC('QUARTER', launch_date), DATE_TRUNC('MONTH', launch_date));
